from pathlib import Path
import json,hashlib
ROOT=Path(__file__).resolve().parents[1];DOC=ROOT.parent/'docs';DOC.mkdir(exist_ok=True)
def sha(p):return hashlib.sha256((ROOT/p).read_bytes()).hexdigest()
datasets=[
 {'id':'dhaka-water-v1','title':'Water Quality and Hydroclimatic Dataset for Rivers and Streams of Dhaka, Bangladesh','doi':'10.17632/xftpv7jvx3.1','version':'1','authors':'Parishmita Sinha; Nirab Debnath; Prithwiraj Bhattacharjee','url':'https://data.mendeley.com/datasets/xftpv7jvx3/1','license':'CC BY 4.0','acquired':'2026-10-20','path':'research/water/Water quality.csv','size':'1,495 records; 58 coordinate pairs; 60 river/location name combinations; 104 dates','period':'2017-01-25 to 2021-07-17','used':'GIS; pH/DO/COD screening; DO model training and temporal evaluation','transform':'Normalize Tongi Khal casing; flag six invalid negative-value rows; retain raw file; do not use supplied WQI or Pollution_Label; keep unspecified nutrient chemical forms out of objective comparisons.','limits':'Repository-published measurements, not independently verified lab results. Original QA/custody documentation is incomplete. Historical, geographically limited and temporally clustered.'},
 {'id':'basis-v2','title':'Dataset for the BASIS Framework: High-Resolution Spatial, Diurnal, and Hydraulic Fecal Pollution Tracking in Resource-Limited Urban Channels','doi':'10.17632/bncwnj8yjt.2','version':'2','authors':'Bijit Kumar Banik; Rahul Das Gupta; Md. Hasibul Chowdhury; Imran Hasan; Md. Imran Kabir; Muhammad Azizul Hoque','url':'https://data.mendeley.com/datasets/bncwnj8yjt/2','license':'CC BY 4.0','acquired':'2026-10-20','path':'research/water/basis-v2.xlsx','size':'Seven worksheets; extracted 40 velocity points, six hydraulic groups and 62 unlocated quality samples','period':'February 2025 quality campaign; May 16, 2025 velocity survey; hydraulic-group timestamps absent','used':'Separate survey GIS layer; mixing/closure investigation examples; explicit unlocated-sample audit','transform':'Read published mean concentrations; multiply FC means by 10^5 to CFU/100 mL; do not count replicates as independent sites; do not join survey numeric IDs to quality-station IDs.','limits':'No industrial-emitter labels. The actual quality worksheet lacks the coordinates suggested in broad metadata. No invented geolocation or complete urban-drain topology.'},
 {'id':'nasa-power-snapshot','title':'NASA POWER monthly PRECTOTCORR at 22.57 N, 89.51 E','doi':None,'version':'Retained API snapshot','authors':'NASA POWER','url':'https://power.larc.nasa.gov/docs/services/api/temporal/monthly/','license':'NASA data attribution; source terms apply','acquired':'2026-10-17','path':'research/raw/power.txt','size':'Monthly point request, 1983–2025','period':'1983–2025; experiment targets 1984–2025','used':'Separate retrospective low-rainfall experiment','transform':'Convert mm/day monthly means to mm/month using calendar day counts; thresholds computed only from training.','limits':'Gridded model-derived data, not a local rain gauge; historical revisions and current endpoints can change. Not a live tank-stock feed.'},
 {'id':'noaa-roni-snapshot','title':'NOAA CPC Relative Oceanic Nino Index historical table','doi':None,'version':'ERSSTv6 historical table snapshot','authors':'NOAA Climate Prediction Center','url':'https://www.cpc.ncep.noaa.gov/products/analysis_monitoring/enso/roni/','license':'NOAA attribution; source terms apply','acquired':'2026-10-17','path':'research/raw/roni.txt','size':'Historical three-month seasonal index table','period':'Historical table used for lagged 1984–2025 experiment','used':'Candidate climate feature and baseline comparison','transform':'Index values by center month; target-month minus three lag, with season ending before target.','limits':'Modern historical revisions; not as-issued hindcasts. RONI addition did not improve Brier loss. No local storm/salinity attribution.'},
 {'id':'ecr2023-reference','title':'Bangladesh Environment Conservation Rules 2023','doi':None,'version':'Gazette March 5, 2023; Schedule 2(a)(1), fisheries row','authors':'Government of Bangladesh / Bangladesh Government Press','url':'https://www.dpp.gov.bd/upload_file/gazettes/47999_44880.pdf','license':'Official regulatory reference; no endorsement implied','acquired':'2026-10-20','path':'research/water/ecr2023.pdf','size':'107-page Gazette PDF; relevant table on PDF p.53 / printed p.3061','period':'2023 reference used retrospectively','used':'pH 6–9, DO >=5 mg/L and COD <=50 mg/L screening objectives','transform':'Visual transcription from the rendered table; no reliance on garbled extracted Bengali text.','limits':'Only three matched parameters used. Intended use is inland fisheries. This is not finished drinking-water assessment, effluent compliance or a legal finding about pre-2023 samples.'}
]
for d in datasets:d['sha256']=sha(d['path']);d['bytes']=(ROOT/d['path']).stat().st_size
(ROOT/'DATASETS.json').write_text(json.dumps(datasets,indent=2),encoding='utf-8')
lines=['# Dataset register','', 'Release documentation: 21 October 2026. Acquisition dates refer to project downloads, not sampling dates. All raw snapshots are retained. Publisher checksums matched for both water datasets. A matching checksum proves the downloaded file matches the publisher, not that every measurement is scientifically correct.','']
for d in datasets:
 lines += ['## '+d['title'],'',f"Source: {d['url']}",f"Authors/provider: {d['authors']}",f"Version: {d['version']}"+(f"; DOI {d['doi']}" if d['doi'] else ''),f"License/basis: {d['license']}",f"Acquired: {d['acquired']}",f"Coverage: {d['size']}",f"Observation/reference period: {d['period']}",'',f"Local raw file: `prototype/{d['path']}` ({d['bytes']:,} bytes)",f"SHA-256: `{d['sha256']}`",'', '**Use.** '+d['used'], '**Transformation.** '+d['transform'], '**Limitations.** '+d['limits'],'']
lines += ['## Additional sources and boundaries','', '- OpenStreetMap provides online contextual tiles, with attribution and ODbL terms. No industrial-discharge inventory, verified outlet network or source culpability is inferred from map proximity.','- CCME 2017 supplies the index method and sampling guidance. Its method is implemented, but no standard CCME score is displayed for the three-parameter default panel.','- WHO small-supply inspection guidance and EPA source-investigation/sampling guidance inform the pilot workflow; their presence is not a certification of this prototype.','- REACH, SafePani, MIT and YC/Waterplan were used for contextual and venture research. REACH raw records are not used to train the shipped DO model.','- FFWC, CHIRPS, HydroRIVERS and live BMD feeds are not integrated in this release. Do not list them as operational data inputs.','- The continuity scenarios are explicitly synthetic configurations in `src/engine.mjs`, not observed community records.','', '## Download and audit','', 'Use `prototype/scripts/fetch-water.py` to verify or reacquire the exact pinned water files. Use `node scripts/verify-manifest.mjs` inside `prototype/` to check the release evidence files. Consult `ATTRIBUTIONS.md` for credit and reuse details.','']
(DOC/'DATASETS.md').write_text('\n\n'.join(lines),encoding='utf-8')
print('Wrote five-source dataset register and machine-readable metadata.')
